#include "ESPluginFactory.h"

#include <stdexcept>

namespace edm {
  namespace ESPluginFactory {
    namespace impl {

// The following comment is generated by an LLM. 
/**
 * Adds a new plugin to the registry.
 *
 * @param name   the unique identifier of the plugin
 * @param maker  the creator of the plugin instance
 *
 * @throws stdlogicerror if a plugin with the same name is already registered
 */ 
      void Registry::add(std::string const& name, std::unique_ptr<MakerBase> maker) {
        auto found = pluginRegistry_.find(name);
        if (found != pluginRegistry_.end()) {
          throw std::logic_error("Plugin " + name + " is already registered");
        }
        pluginRegistry_.emplace(name, std::move(maker));
      }


// The following comment is generated by an LLM. 
/**
 * Retrieves a MakerBase object from the registry based on its name.
 *
 * @param name The name of the MakerBase object to retrieve.
 * @return A pointer to the MakerBase object associated with the given name.
 * @throws stdlogicerror If the specified name is not found in the registry.*/ 
      MakerBase const* Registry::get(std::string const& name) {
        auto found = pluginRegistry_.find(name);
        if (found == pluginRegistry_.end()) {
          throw std::logic_error("Plugin " + name + " is not registered");
        }
        return found->second.get();
      }


// The following comment is generated by an LLM. 
/**
 * Returns the global registry instance 
 */ 
      Registry& getGlobalRegistry() {
        static Registry reg;
        return reg;
      }
    };  // namespace impl

    std::unique_ptr<ESProducer> create(std::string const& name, std::string const& datadir) {
      return impl::getGlobalRegistry().get(name)->create(datadir);
    }
  }  // namespace ESPluginFactory
}  // namespace edm
